// Karbon (practice management for accounting firms) on Karbon's API v3: every operation in its OpenAPI spec.
// actions.json is generated by `bun scripts/openapi-actions.ts karbon`; contacts, organizations, client groups, work
// items, notes, invoices, budgets and custom fields start automations by webhook (triggers.ts), the rest by polling
// (polls/karbon.ts). Every call carries two keys: Emplio's Application key from Karbon (KARBON_APP_KEY, the Bearer
// token) and the firm's own Access Key (the AccessKey header), which is what the owner pastes.
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { AppsError } from "../../types";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const appKey = () => {
  const k = process.env.KARBON_APP_KEY;
  if (!k) throw new AppsError("this Emplio server can't connect Karbon yet: its Karbon application key (KARBON_APP_KEY) isn't set");
  return k;
};

export const api: Api = {
  name: "Karbon",
  base: "https://api.karbonhq.com",
  tokenHelp: "Karbon → Settings → Connected Apps → Emplio",
  auth: (key) => ({ Authorization: `Bearer ${appKey()}`, AccessKey: key }),
};

export const karbon: OwnApp = {
  app: "karbon",
  name: "Karbon",
  logo: "/logos/karbon.svg",
  keyField: {
    label: "Access Key",
    help: "In Karbon, open Settings → Connected Apps, find Emplio and create an Access Key, then copy it here (it's a long code starting with eyJ). Only a Karbon admin can do this. Emplio can then see and change your firm's contacts, work, notes, time and billing.",
    placeholder: "eyJhbGciOi...",
  },
  async check(key) {
    appKey();
    // ponytail: Karbon's API has no call that names the firm, so the label is generic
    await call(api, key, { method: "GET", path: "/v3/TenantSettings", query: [], headers: [] }, {});
    return "Karbon";
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(api, delivery, key),
    wanted,
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
